import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Plane geometry (unit size, will be scaled by parent adapter if needed)
  const geometry = new ctx.THREE.PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });
  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously; apply when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // No primitives to apply for this node
  // No text content to render

  // Event handlers placeholder (none defined)
  group.userData.handlers = {};

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // No GSAP timelines were created, but kill any if they existed
    if (group.userData._gsapTimelines) {
      group.userData._gsapTimelines.forEach((tl) => tl.kill());
    }
  };

  return group;
}
